//! Prints the function reference for `datafusion-spark` as Markdown.
//!
//! The content comes from each function's `documentation()`, which is generated by the
//! `#[user_doc]` attribute. Usage:
//!
//! ```text
//! cargo run -p datafusion-spark-docgen --bin print_functions_docs
//! ```
//!
//! Called from `dev/update_function_docs.sh`, which writes the output to `docs/functions.md`.
//! Functions that don't implement `documentation()` yet are listed on stderr.

use datafusion_expr::{
    DocSection, Documentation, aggregate_doc_sections, scalar_doc_sections,
    window_doc_sections,
};
use std::fmt::Write as _;

/// Name, aliases and documentation of a scalar, aggregate or window function.
struct FunctionDoc {
    name: String,
    aliases: Vec<String>,
    documentation: Option<Documentation>,
}

/// Collects [`FunctionDoc`]s from a list of `ScalarUDF`s, `AggregateUDF`s or `WindowUDF`s,
/// which share these methods but no common trait.
macro_rules! function_docs {
    ($udfs:expr) => {
        $udfs
            .iter()
            .map(|f| FunctionDoc {
                name: f.name().to_string(),
                aliases: f.aliases().to_vec(),
                documentation: f.documentation().cloned(),
            })
            .collect::<Vec<_>>()
    };
}

fn main() {
    let scalar: Vec<FunctionDoc> =
        function_docs!(datafusion_spark::all_default_scalar_functions());
    let aggregate: Vec<FunctionDoc> =
        function_docs!(datafusion_spark::all_default_aggregate_functions());
    let window: Vec<FunctionDoc> =
        function_docs!(datafusion_spark::all_default_window_functions());

    let mut docs = String::new();
    let mut undocumented = Vec::new();
    for (title, functions, known_sections) in [
        (
            "Scalar Functions",
            &scalar,
            scalar_doc_sections::doc_sections(),
        ),
        (
            "Aggregate Functions",
            &aggregate,
            aggregate_doc_sections::doc_sections(),
        ),
        (
            "Window Functions",
            &window,
            window_doc_sections::doc_sections(),
        ),
    ] {
        print_function_type(&mut docs, title, functions, &known_sections);
        undocumented.extend(
            functions
                .iter()
                .filter(|f| f.documentation.is_none())
                .map(|f| format!("{} ({})", f.name, title.to_lowercase())),
        );
    }

    print!("{docs}");

    if !undocumented.is_empty() {
        undocumented.sort();
        eprintln!(
            "INFO: {} functions do not implement `documentation()` yet:",
            undocumented.len()
        );
        for name in undocumented {
            eprintln!("  - {name}");
        }
    }
}

/// Writes one function type (scalar, aggregate or window), grouped by doc section.
///
/// Sections follow DataFusion's order. Sections that DataFusion doesn't define (for example
/// "URL Functions") come after it, sorted by label.
fn print_function_type(
    docs: &mut String,
    title: &str,
    functions: &[FunctionDoc],
    known_sections: &[DocSection],
) {
    let mut sections: Vec<&DocSection> = Vec::new();
    for section in functions
        .iter()
        .filter_map(|f| f.documentation.as_ref())
        .map(|d| &d.doc_section)
        .filter(|s| s.include)
    {
        if !sections.iter().any(|s| s.label == section.label) {
            sections.push(section);
        }
    }
    if sections.is_empty() {
        return;
    }
    let rank = |s: &DocSection| {
        known_sections
            .iter()
            .position(|k| k.label == s.label)
            .unwrap_or(known_sections.len())
    };
    sections.sort_by(|a, b| rank(a).cmp(&rank(b)).then(a.label.cmp(b.label)));

    let _ = writeln!(docs, "\n## {title}");
    for section in sections {
        print_section(docs, section, functions);
    }
}

fn print_section(docs: &mut String, section: &DocSection, functions: &[FunctionDoc]) {
    let functions: Vec<&FunctionDoc> = functions
        .iter()
        .filter(|f| {
            f.documentation
                .as_ref()
                .is_some_and(|d| d.doc_section.label == section.label)
        })
        .collect();

    let _ = writeln!(docs, "\n### {}\n", section.label);
    if let Some(description) = section.description {
        let _ = writeln!(docs, "{description}\n");
    }

    // Function names and aliases, sorted, so that aliases can be looked up too
    let mut names: Vec<(&str, &FunctionDoc)> = functions
        .iter()
        .flat_map(|f| {
            std::iter::once(f.name.as_str())
                .chain(f.aliases.iter().map(String::as_str))
                .map(move |n| (n, *f))
        })
        .collect();
    names.sort_by_key(|(n, _)| *n);

    for (name, _) in &names {
        let _ = writeln!(docs, "- [{name}](#{name})");
    }

    for (name, f) in names {
        if name != f.name {
            let _ = writeln!(docs, "\n#### `{name}`\n");
            let _ = writeln!(docs, "_Alias of [{0}](#{0})._", f.name);
            continue;
        }
        let Some(d) = &f.documentation else {
            unreachable!("only documented functions are in a section")
        };

        let _ = writeln!(docs, "\n#### `{name}`\n");
        let _ = writeln!(docs, "{}\n", d.description);
        let _ = writeln!(docs, "```sql\n{}\n```", d.syntax_example);

        if let Some(args) = &d.arguments {
            let _ = writeln!(docs, "\n##### Arguments\n");
            for (arg_name, arg_desc) in args {
                let _ = writeln!(docs, "- **{arg_name}**: {arg_desc}");
            }
        }

        if let Some(example) = &d.sql_example {
            let _ = writeln!(docs, "\n##### Example\n\n{example}");
        }

        if let Some(alt_syntax) = &d.alternative_syntax {
            let _ = writeln!(docs, "\n##### Alternative Syntax\n");
            for syntax in alt_syntax {
                let _ = writeln!(docs, "```sql\n{syntax}\n```");
            }
        }

        if !f.aliases.is_empty() {
            let _ = writeln!(docs, "\n##### Aliases\n");
            for alias in &f.aliases {
                let _ = writeln!(docs, "- {}", alias.replace('_', r"\_"));
            }
        }

        if let Some(related) = &d.related_udfs {
            let _ = writeln!(docs, "\n**Related functions**:\n");
            for r in related {
                let _ = writeln!(docs, "- [{r}](#{r})");
            }
        }
    }
}
